-- 106 AI outbox dispatcher claim leases and owner fencing; forward-only and idempotent.
SET @schema_name=DATABASE();
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_outbox' AND COLUMN_NAME='lease_owner'),'ALTER TABLE `fun_ai_outbox` ADD COLUMN `lease_owner` varchar(128) NULL AFTER `status`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_outbox' AND COLUMN_NAME='lease_expires_at'),'ALTER TABLE `fun_ai_outbox` ADD COLUMN `lease_expires_at` datetime NULL AFTER `lease_owner`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_outbox' AND COLUMN_NAME='status' AND COLUMN_TYPE NOT LIKE '%processing%'),'ALTER TABLE `fun_ai_outbox` MODIFY COLUMN `status` enum(\'pending\',\'processing\',\'dispatched\',\'failed\') NOT NULL DEFAULT \'pending\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_outbox' AND INDEX_NAME='idx_ai_outbox_claim'),'ALTER TABLE `fun_ai_outbox` ADD KEY `idx_ai_outbox_claim` (`status`,`available_at`,`lease_expires_at`,`id`)','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
